const A='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
function enc(buf){let z=0;while(z<buf.length&&buf[z]===0)z++;let n=0n;for(const b of buf)n=n*256n+BigInt(b);let s='';while(n>0n){s=A[Number(n%58n)]+s;n/=58n;}return A[0].repeat(z)+s;}
const m=process.argv[2];
if(m==='hex'){console.log(enc(Buffer.from(process.argv[3],'hex')));}
else if(m==='rep'){console.log(enc(Buffer.from(process.argv[3].repeat(parseInt(process.argv[4])),'binary')));}
else if(m==='range'){const a=+process.argv[3],b=+process.argv[4];const arr=[];for(let i=a;i<=b;i++)arr.push(i);console.log(enc(Buffer.from(arr)));}
else if(m==='str'){console.log(enc(Buffer.from(process.argv[3],'utf8')));}
EOF
